/**
 * @file RoomInfo.js
 * 
 * @description A component for displaying information about a room. 
 *              It shows the room code, the name of the room owner, 
 *              and a list of players in the room, including their ID and color.
 * 
 * @author Vámi zadané jméno
 * 
 * @props {string} roomCode - The unique code of the room.
 * @props {Array} players - An array of players in the room. 
 *        Each player has properties such as `id`, `name`, and `color`.
 * @props {string} ownerName - The name of the room owner.
 */

import React, { useState } from 'react';
import './RoomInfo.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCopy, faEdit } from '@fortawesome/free-solid-svg-icons';

function RoomInfo({ roomCode, players, ownerName }) {
  const [statusMessage, setStatusMessage] = useState(""); 
  const [editablePlayers, setEditablePlayers] = useState(players);

  const copyToClipboard = () => {
    navigator.clipboard.writeText(roomCode)
      .then(() => {
        setStatusMessage("Room code copied");
      })
      .catch(err => {
        setStatusMessage("Failed to copy text");
        console.error('Failed to copy text: ', err);
      });
  };

  const handleNameChange = (id, newName) => {
    setEditablePlayers(prevPlayers =>
      prevPlayers.map(player =>
        player.id === id ? { ...player, name: newName } : player
      )
    );
  };

  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
        <h2 style={{ margin: 0, fontSize: '1.5rem' }}>
          Room code: <span>{roomCode}</span>
        </h2>
        <button
          onClick={copyToClipboard}
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '5px',
            cursor: 'pointer',
            border: 'none',
            background: 'transparent',
            fontSize: '1.2rem',
            alignSelf: 'flex-end',
            marginTop: '10px',
          }}
        >
          <FontAwesomeIcon icon={faCopy} /> Copy
        </button>
        {statusMessage && <div className="status-message2">{statusMessage}</div>}
      </div>
      <h3>Room owner: {ownerName}</h3>
      <h3>Player:</h3>
      <ul>
        {editablePlayers && editablePlayers.map((player) => (
          <li key={player.id} style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <input
              type="text"
              value={player.name}
              onChange={(e) => handleNameChange(player.id, e.target.value)}
              style={{ marginRight: '10px', fontSize: '1rem' }}
            />
            (ID: {player.id}, Color: {player.color || 'No color'})
            <FontAwesomeIcon icon={faEdit} style={{ marginLeft: '10px', cursor: 'pointer' }} />
          </li>
        ))}
      </ul>
    </div>
  );
}

export default RoomInfo;
